import json, re, pathlib

root = pathlib.Path(".")
man = json.loads((root/"inputs/repo-manifest.json").read_text())

exists, removed = set(), {}
for cat, blk in man.items():
    if not isinstance(blk, dict): continue
    for p in blk.get("exists", []):
        exists.add(p)
        if cat == "scripts": exists.add("scripts/"+p); exists.add("./scripts/"+p)
    for p in blk.get("removed", []):
        removed[p] = cat
        if cat == "scripts":
            removed["scripts/"+p] = cat; removed["./scripts/"+p] = cat

docs = ["inputs/AGENTS.md", "inputs/README.md", "inputs/docs/ops/runbook.md"]
# candidate references: paths with a slash or known extension, plus /api/ endpoints
pat = re.compile(r"(?:\./)?(?:[\w.\-/]+\.(?:ts|md|sh|yaml|yml|json|log|example))|(?:/api/v\d+/[\w/]+)")

for d in docs:
    text = (root/d).read_text()
    seen = []
    for m in pat.finditer(text):
        r = m.group(0)
        if r not in seen: seen.append(r)
    print(f"\n=== {d} ===")
    for r in seen:
        norm = r[2:] if r.startswith("./") else r
        if r in removed or norm in removed:
            print(f"  REMOVED  {r}   (manifest category: {removed.get(r, removed.get(norm))})")
        elif r in exists or norm in exists:
            print(f"  OK       {r}")
        else:
            print(f"  UNKNOWN  {r}   (not in manifest either list)")

print("\n=== manifest items that exist but are referenced in NO doc ===")
alltext = "\n".join((root/d).read_text() for d in docs)
for p in sorted(exists):
    if p.startswith("./") or p.startswith("scripts/"): continue
    if p not in alltext:
        print(f"  UNDOCUMENTED  {p}")
